import { Button } from '@patternfly/react-core/dist/dynamic/components/Button';
import { Divider } from '@patternfly/react-core/dist/dynamic/components/Divider';
import { EmptyState } from '@patternfly/react-core/dist/dynamic/components/EmptyState';
import { EmptyStateBody } from '@patternfly/react-core/dist/dynamic/components/EmptyState';
import { Menu } from '@patternfly/react-core/dist/dynamic/components/Menu';
import { MenuContent } from '@patternfly/react-core/dist/dynamic/components/Menu';
import { MenuGroup } from '@patternfly/react-core/dist/dynamic/components/Menu';
import { MenuSearch } from '@patternfly/react-core/dist/dynamic/components/Menu';
import { MenuSearchInput } from '@patternfly/react-core/dist/dynamic/components/Menu';
import { MenuItem } from '@patternfly/react-core/dist/dynamic/components/Menu';
import { MenuList } from '@patternfly/react-core/dist/dynamic/components/Menu';
import { TextInput } from '@patternfly/react-core/dist/dynamic/components/TextInput';
import { EmptyStateActions } from '@patternfly/react-core/dist/dynamic/components/EmptyState';
import { EmptyStateFooter } from '@patternfly/react-core/dist/dynamic/components/EmptyState';
import { Tooltip } from '@patternfly/react-core/dist/dynamic/components/Tooltip';
import { TooltipPosition } from '@patternfly/react-core/dist/dynamic/components/Tooltip';
import fuzzysearch from 'fuzzysearch';
import { useTranslation } from 'react-i18next';
import ProjectMenuToggle from './ProjectMenuToggle';
import { alphanumericCompare } from './utils';
import { useEditableProjects } from '../../hooks/useEditableProjects';
import {
  ChangeEvent,
  FC,
  MutableRefObject,
  MouseEvent as ReactMouseEvent,
  Ref,
  useCallback,
  useMemo,
  useRef,
  useState,
} from 'react';
import { ALL_NAMESPACES_KEY } from '../../../../shared/utils/utils';

export const NoResults: FC<{
  onClear: (event: ReactMouseEvent<HTMLButtonElement, MouseEvent>) => void;
}> = ({ onClear }) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  return (
    <>
      <Divider />
      <EmptyState headingLevel="h4" titleText={<>{t('No projects found')}</>}>
        <EmptyStateBody>{t('No results match the filter criteria.')}</EmptyStateBody>
        <EmptyStateFooter>
          <EmptyStateActions>
            <Button variant="link" onClick={onClear}>
              {t('Clear filters')}
            </Button>
          </EmptyStateActions>
        </EmptyStateFooter>
      </EmptyState>
    </>
  );
};

/* ****************************************** */

export const Filter: FC<{
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  filterRef: Ref<any>;
  onFilterChange: (filterText: string) => void;
  filterText: string;
}> = ({ filterText, filterRef, onFilterChange }) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  return (
    <MenuSearch>
      <MenuSearchInput>
        <TextInput
          data-test="dropdown-text-filter"
          autoFocus
          value={filterText}
          aria-label={t('Select project...')}
          type="search"
          placeholder={t('Select project...')}
          onChange={(_, value: string) => onFilterChange(value)}
          ref={filterRef}
        />
      </MenuSearchInput>
    </MenuSearch>
  );
};

/* ****************************************** */

export const ProjectGroup: FC<{
  options: { key: string; title: string }[];
  selectedKey: string;
}> = ({ options, selectedKey }) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);

  return options.length === 0 ? null : (
    <>
      <Divider />
      <MenuGroup label={t('Projects')}>
        <MenuList>
          {options.map((option) => {
            return (
              <MenuItem
                key={option.key}
                itemId={option.key}
                isSelected={selectedKey === option.key}
                data-test="dropdown-menu-item-link"
              >
                {option.title}
              </MenuItem>
            );
          })}
        </MenuList>
      </MenuGroup>
    </>
  );
};

/* ****************************************** */

const ProjectMenu: FC<{
  setOpen: (isOpen: boolean) => void;
  onSelect: (event: ReactMouseEvent, itemId: string) => void;
  selected?: string;
  menuRef: MutableRefObject<HTMLDivElement>;
}> = ({ setOpen, onSelect, selected, menuRef }) => {
  const filterRef = useRef(null);
  const { t } = useTranslation(process.env.I18N_NAMESPACE);

  const [filterText, setFilterText] = useState('');

  const { allProjects } = useEditableProjects();

  const optionItems = useMemo(() => {
    const items =
      allProjects?.map((projectName) => {
        return { title: projectName, key: projectName };
      }) || [];

    items.sort((a, b) => alphanumericCompare(a.title, b.title));
    items.unshift({ title: t('All Projects'), key: ALL_NAMESPACES_KEY });
    if (selected && !items.some((option) => option.key === selected)) {
      items.unshift({ title: selected, key: selected }); // Add current project if it isn't included
    }

    return items;
  }, [allProjects, selected, t]);

  const isOptionShown = useCallback(
    (option) => {
      return fuzzysearch(filterText.toLowerCase(), option.title.toLowerCase());
    },
    [filterText],
  );

  const { filteredOptions } = useMemo(
    () =>
      optionItems.reduce(
        (filtered, option) => {
          if (isOptionShown(option)) {
            filtered.filteredOptions.push(option);
          }
          return filtered;
        },
        { filteredOptions: [] },
      ),
    [isOptionShown, optionItems],
  );

  return (
    <Menu
      ref={menuRef}
      className="co-namespace-dropdown__menu"
      onSelect={(event: ReactMouseEvent, itemId: string) => {
        setOpen(false);
        onSelect(event, itemId);
      }}
      activeItemId={selected}
      data-test="project-dropdown-menu"
      isScrollable
    >
      <MenuContent maxMenuHeight="60vh" className="co-namespace-dropdown__menu-content">
        <Filter filterRef={filterRef} onFilterChange={setFilterText} filterText={filterText} />
        {filteredOptions.length === 0 ? (
          <NoResults
            onClear={(event) => {
              event.preventDefault();
              event.stopPropagation();
              setFilterText('');
              filterRef.current?.focus();
            }}
          />
        ) : null}
        <ProjectGroup options={filteredOptions} selectedKey={selected} />
      </MenuContent>
    </Menu>
  );
};

/* ****************************************** */

const ProjectDropdown: FC<ProjectDropdownProps> = ({ disabled, onSelect, selected, shortCut }) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const menuRef = useRef(null);
  const [isOpen, setOpen] = useState(false);
  const { allProjects, permissionsLoading, permissionsError } = useEditableProjects();

  const menuProps = {
    setOpen,
    onSelect,
    selected,
    menuRef,
  };

  let title = t('All Projects');
  // While loading permissions, or if there is a permission error fallback to the "selected" value
  // 'All Projects' is the user friendly ALL_NAMESPACES_KEY
  if (
    selected &&
    (allProjects?.includes(selected) || permissionsLoading || !!permissionsError) &&
    selected !== ALL_NAMESPACES_KEY
  ) {
    title = selected;
  }

  const toggle = (
    <ProjectMenuToggle
      disabled={disabled || permissionsLoading || !!permissionsError}
      menu={<ProjectMenu {...menuProps} />}
      menuRef={menuRef}
      isOpen={isOpen}
      title={`${t('Project')}: ${title}`}
      onToggle={(menuState) => {
        setOpen(menuState);
      }}
      shortCut={shortCut}
    />
  );

  return (
    <div className="co-namespace-dropdown">
      {permissionsLoading ? (
        <Tooltip content={t('Checking permissions...')} position={TooltipPosition.bottom}>
          {toggle}
        </Tooltip>
      ) : permissionsError ? (
        <Tooltip
          content={t('Failed to load project permissions. Please refresh the page and try again.')}
          position={TooltipPosition.bottom}
        >
          {toggle}
        </Tooltip>
      ) : (
        toggle
      )}
    </div>
  );
};

type ProjectDropdownProps = {
  disabled?: boolean;
  onSelect?: (event: ReactMouseEvent | ChangeEvent, value: string) => void;
  shortCut?: string;
  selected?: string;
};

export default ProjectDropdown;
