import { createContext, useContext, useState, ReactNode, FC } from 'react';
import { useTranslation } from 'react-i18next';
import { Alert } from '@patternfly/react-core/dist/dynamic/components/Alert';
import { AlertProps } from '@patternfly/react-core/dist/dynamic/components/Alert';
import { AlertGroup } from '@patternfly/react-core/dist/dynamic/components/Alert';
import { AlertActionCloseButton } from '@patternfly/react-core/dist/dynamic/components/Alert';
import { AlertVariant } from '@patternfly/react-core/dist/dynamic/components/Alert';

interface ToastItem {
  key: string;
  title: string;
  variant: AlertProps['variant'];
}

interface ToastContextType {
  addAlert: (title: string, variant: AlertProps['variant']) => void;
  removeAlert: (key: string) => void;
  alerts: ToastItem[];
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const useToast = () => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error(t('useToast must be used within ToastProvider'));
  }
  return context;
};

export const ToastProvider: FC<{ children: ReactNode }> = ({ children }) => {
  const [alerts, setAlerts] = useState<ToastItem[]>([]);

  const addAlert = (title: string, variant: AlertProps['variant']) => {
    const key = new Date().getTime().toString();
    setAlerts((prevAlerts) => [{ title, variant, key }, ...prevAlerts]);
  };

  const removeAlert = (key: string) => {
    setAlerts((prevAlerts) => prevAlerts.filter((alert) => alert.key !== key));
  };

  return (
    <ToastContext.Provider value={{ addAlert, removeAlert, alerts }}>
      {children}
      <AlertGroup hasAnimations isToast isLiveRegion>
        {alerts.map(({ key, variant, title }) => (
          <Alert
            variant={AlertVariant[variant]}
            title={title}
            actionClose={
              <AlertActionCloseButton
                title={title}
                variantLabel={`${variant} alert`}
                onClose={() => removeAlert(key)}
              />
            }
            key={key}
          />
        ))}
      </AlertGroup>
    </ToastContext.Provider>
  );
};
